export const questions = originalQuestions.map(question => {
  const translation = translations[Number(question.id.slice(1))];
  const sourceLabel = sourceLabels[question.source.label];
  const difficulty = difficultyLabels[question.difficulty];
  if (!translation || !sourceLabel || !difficulty) {
    throw new Error(`Missing English question translation: ${question.id}`);
  }
  return {
    ...question,
    ...translation,
    difficulty,
    answers: [...question.answers],
    source: { ...question.source, label: sourceLabel }
  };
});
